import{_ as n,o as i,c as e,ai as s}from"./chunks/framework.CaiDwmc7.js";const k=JSON.parse('{"title":"Panduan Penggunaan .gitignore","description":"","frontmatter":{},"headers":[],"relativePath":"gitignore-guide.md","filePath":"gitignore-guide.md"}'),t={name:"gitignore-guide.md"};function l(r,a,p,o,d,g){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="panduan-penggunaan-gitignore" tabindex="-1">Panduan Penggunaan .gitignore <a class="header-anchor" href="#panduan-penggunaan-gitignore" aria-label="Permalink to “Panduan Penggunaan .gitignore”">​</a></h1><p>Dokumen ini menjelaskan fungsi dan cara menggunakan file <code>.gitignore</code> untuk mengabaikan file atau direktori agar tidak dilacak oleh Git.</p><h2 id="_1-apa-itu-gitignore" tabindex="-1">1. Apa itu .gitignore? <a class="header-anchor" href="#_1-apa-itu-gitignore" aria-label="Permalink to “1. Apa itu .gitignore?”">​</a></h2><p><code>.gitignore</code> adalah file teks yang memberi tahu Git file atau folder mana yang harus diabaikan dalam sebuah proyek. Ini sangat berguna untuk mencegah file sensitif, file konfigurasi lokal, atau folder dependensi (seperti <code>node_modules</code>) masuk ke repositori.</p><h2 id="_2-cara-membuat-gitignore" tabindex="-1">2. Cara Membuat .gitignore <a class="header-anchor" href="#_2-cara-membuat-gitignore" aria-label="Permalink to “2. Cara Membuat .gitignore”">​</a></h2><p>Cukup buat file bernama <code>.gitignore</code> di root direktori proyek Anda.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .gitignore</span></span></code></pre></div><h2 id="_3-contoh-isi-gitignore-umum" tabindex="-1">3. Contoh Isi .gitignore Umum <a class="header-anchor" href="#_3-contoh-isi-gitignore-umum" aria-label="Permalink to “3. Contoh Isi .gitignore Umum”">​</a></h2><p>Berikut adalah contoh isi file <code>.gitignore</code> untuk proyek web (Node.js/PHP):</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Dependensi</span></span>
<span class="line"><span>node_modules/</span></span>
<span class="line"><span>vendor/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Environment Variables (Sangat Penting!)</span></span>
<span class="line"><span>.env</span></span>
<span class="line"><span>.env.local</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Log</span></span>
<span class="line"><span>*.log</span></span>
<span class="line"><span>npm-debug.log*</span></span>
<span class="line"><span></span></span>
<span class="line"><span># OS Files</span></span>
<span class="line"><span>.DS_Store</span></span>
<span class="line"><span>Thumbs.db</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Build Output</span></span>
<span class="line"><span>dist/</span></span>
<span class="line"><span>build/</span></span></code></pre></div><h2 id="_4-aturan-penulisan-syntax" tabindex="-1">4. Aturan Penulisan (Syntax) <a class="header-anchor" href="#_4-aturan-penulisan-syntax" aria-label="Permalink to “4. Aturan Penulisan (Syntax)”">​</a></h2><ul><li><code>folder/</code> : Mengabaikan seluruh isi folder tersebut.</li><li><code>*.log</code> : Mengabaikan semua file yang berakhiran <code>.log</code>.</li><li><code>!penting.log</code> : Tanda seru (<code>!</code>) digunakan untuk mengecualikan file agar tetap dilacak meskipun polanya cocok dengan aturan abaikan.</li><li><code>/file.txt</code> : Hanya mengabaikan <code>file.txt</code> di root direktori, bukan di subfolder.</li></ul><h2 id="_5-cara-mengabaikan-file-yang-sudah-terlanjur-di-track" tabindex="-1">5. Cara Mengabaikan File yang Sudah Terlanjur Di-track <a class="header-anchor" href="#_5-cara-mengabaikan-file-yang-sudah-terlanjur-di-track" aria-label="Permalink to “5. Cara Mengabaikan File yang Sudah Terlanjur Di-track”">​</a></h2><p>Jika Anda baru menambahkan file ke <code>.gitignore</code> setelah file tersebut terlanjur di-commit, Git akan tetap melacaknya. Gunakan perintah ini untuk menghapusnya dari cache Git (tanpa menghapus file fisiknya):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Update .gitignore: stop tracking ignored files&quot;</span></span></code></pre></div><hr><p><em>Dibuat untuk dokumentasi internal proyek Avery PHP.</em></p>`,17)])])}const u=n(t,[["render",l]]);export{k as __pageData,u as default};
